const body = $input.first().json;
if (!body.resume_text) throw new Error('resume_text is required');
const rawText = body.resume_text.substring(0, 4000);
return [{ json: {
  resume_text: body.resume_text,
  candidate_id: body.candidate_id || `cand_${Date.now()}`,
  prompt: `You are a professional Resume Extractor. Extract all information from the resume below and return ONLY valid JSON — no explanations, no markdown blocks, just raw JSON.\n\nRequired JSON schema:\n{\"personal_info\":{\"name\":\"\",\"email\":\"\",\"phone\":\"\",\"location\":\"\"},\"education\":[{\"institution\":\"\",\"level\":\"\",\"field\":\"\",\"year\":\"\"}],\"experience\":[{\"company\":\"\",\"role\":\"\",\"duration\":\"\",\"responsibilities\":[]}],\"technical_skills\":[],\"certifications\":[]}\n\nResume Text:\n${rawText}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Setup Input'].json;
let extracted = {};
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  extracted = JSON.parse(m ? m[1] : cleaned);
} catch(e) { extracted = { error: 'parse_failed' }; }
return [{ json: {
  ...prev,
  extraction_results: { structured_data: extracted, status: extracted.error ? 'partial' : 'completed' },
  prompt: `You are a Professional Profile Optimizer. Polish and standardize the extracted resume data below. Fix errors, standardize job titles, and calculate total years of experience. Return ONLY valid JSON — no markdown.\n\n{\"enhanced_summary\":\"\",\"standardized_skills\":[],\"total_years_exp\":0}\n\nInput data:\n${JSON.stringify(extracted)}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Parse ① → Prep ②'].json;
let enhanced = {};
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  enhanced = JSON.parse(m ? m[1] : cleaned);
} catch(e) { enhanced = {}; }
const rawText = (prev.resume_text || '').substring(0,2000);
return [{ json: {
  ...prev,
  enhanced_data: enhanced,
  prompt: `You are a Skills Analyst. Analyze this candidate and classify their seniority. Rules: Junior < 3 years, Mid-level 3-7 years, Senior > 7 years. Return ONLY valid JSON — no markdown.\n\n{\"technical_skills\":[],\"years_of_experience\":0,\"education\":{\"level\":\"\",\"field\":\"\"},\"experience_level\":\"Junior|Mid-level|Senior\",\"key_achievements\":[],\"domain_expertise\":[]}\n\nRaw resume: ${rawText}\nStructured data: ${JSON.stringify(prev.extraction_results?.structured_data || {})}\nEnhanced data: ${JSON.stringify(enhanced)}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Parse ② → Prep ③'].json;
let skills = {};
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  skills = JSON.parse(m ? m[1] : cleaned);
} catch(e) {
  skills = { technical_skills:[], years_of_experience:0, education:{level:'Unknown',field:'Unknown'}, experience_level:'Junior', key_achievements:[], domain_expertise:[] };
}
const topSkills = (skills.technical_skills || []).slice(0,5).join(', ');
const role = `${skills.experience_level || 'Mid-level'} ${(skills.technical_skills||[])[0] || 'Software'} Developer`;
return [{ json: {
  ...prev,
  analysis_results: { skills_analysis: skills, analysis_timestamp: new Date().toISOString().split('T')[0], confidence_score: 0.85 },
  skills_list: skills.technical_skills || [],
  prompt: `You are a Market Intelligence Expert specializing in tech hiring in 2026. Generate 3 realistic, currently-available job listings for a '${role}' candidate. Their top skills: ${topSkills}. Return ONLY valid JSON — no markdown.\n\n{\"market_jobs\":[{\"title\":\"\",\"company\":\"\",\"location\":\"\",\"salary_range\":\"\",\"requirements\":[],\"description\":\"\"}]}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Parse ③ → Prep ④'].json;
const candidateSkillSet = new Set((prev.skills_list || []).map(s => s.toLowerCase()));
let liveJobs = [];
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  const parsed = JSON.parse(m ? m[1] : cleaned);
  liveJobs = parsed.market_jobs || [];
} catch(e) { liveJobs = []; }
const scored = liveJobs.map(job => {
  const reqs = Array.isArray(job.requirements) ? job.requirements : [];
  const reqSet = new Set(reqs.map(r => r.toLowerCase()));
  const score = reqSet.size === 0 ? 75 : Math.round(([...reqSet].filter(r => candidateSkillSet.has(r)).length / reqSet.size) * 100);
  return { title: `${job.title} at ${job.company}`, match_score: score, location: job.location || 'Remote', salary_range: job.salary_range || 'Competitive', requirements: reqs, source: 'Live Market 🌐' };
}).filter(j => j.match_score >= 30).sort((a,b) => b.match_score - a.match_score);
const name = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const ctx = JSON.stringify({ candidate_name: name, skills_analysis: prev.analysis_results.skills_analysis, job_matches: scored.slice(0,3) });
return [{ json: {
  ...prev,
  job_matches: { matched_jobs: scored.slice(0,3), match_timestamp: new Date().toISOString().split('T')[0], number_of_matches: scored.length },
  prompt: `You are a senior HR Screener with 15 years of experience. Evaluate this candidate against the matched job opportunities. Provide a detailed assessment and score (0-100). Return ONLY valid JSON — no markdown.\n\n{\"screening_report\":\"3-4 sentence assessment\",\"screening_score\":75,\"red_flags\":[]}\n\nCandidate data:\n${ctx}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Parse ④ → Prep ⑤'].json;
let screening = {};
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  screening = JSON.parse(m ? m[1] : cleaned);
} catch(e) { screening = { screening_report:'Parse error', screening_score:50, red_flags:[] }; }
const name = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const ctx = JSON.stringify({
  candidate_name: name,
  skills: prev.analysis_results?.skills_analysis?.technical_skills || [],
  years_exp: prev.analysis_results?.skills_analysis?.years_of_experience || 0,
  top_matches: prev.job_matches?.matched_jobs || [],
  screening_score: parseInt(screening.screening_score || 50),
  red_flags: screening.red_flags || []
});
return [{ json: {
  ...prev,
  screening_results: { screening_report: screening.screening_report || 'No report', screening_timestamp: new Date().toISOString(), screening_score: parseInt(screening.screening_score || 50), red_flags: screening.red_flags || [] },
  prompt: `You are the Chief HR Director making a FINAL hiring decision. Be decisive and professional. Return ONLY valid JSON — no markdown.\n\n{\"hiring_status\":\"Recommended|Not Recommended|Pending Review\",\"recommendation\":\"2-3 professional sentence justification\",\"next_steps\":[\"step1\",\"step2\"],\"confidence_level\":\"Low|Medium|High\"}\n\nFull candidate assessment:\n${ctx}`
} }];

const chainText = $input.first().json.text || '';
const prev = $node['Parse ⑤ → Prep ⑥'].json;
let rec = {};
try {
  const cleaned = chainText.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  rec = JSON.parse(m ? m[1] : cleaned);
} catch(e) { rec = { hiring_status:'Pending Review', recommendation:'Manual review required.', next_steps:[], confidence_level:'Low' }; }
const { prompt, resume_text, skills_list, ...clean } = prev;
return [{ json: { ...clean,
  final_recommendation: { hiring_status: rec.hiring_status || 'Pending Review', recommendation: rec.recommendation || 'Manual review required.', next_steps: rec.next_steps || [], recommendation_timestamp: new Date().toISOString(), confidence_level: rec.confidence_level || 'Medium' },
  status: 'completed'
} }];
